CREATE TABLE "connection_models" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "connection_models_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"connection_id" integer NOT NULL,
	"model" text NOT NULL,
	"name" text NOT NULL,
	"enabled" boolean DEFAULT true NOT NULL,
	"is_default" boolean DEFAULT false NOT NULL,
	"capabilities" json DEFAULT '{}'::json NOT NULL,
	"context_window" integer,
	"prompt_format" text,
	"token_counter" text,
	"extra_json" json DEFAULT '{}'::json NOT NULL,
	"sort_order" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "connection_models_identifiers_check" CHECK ("connection_models"."model" <> '' AND "connection_models"."name" <> '')
);
